CREATE OR REPLACE FUNCTION public.can_access_frontdesk_data() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role::text IN ('admin','owner','fo_staff','reception')) $$;
CREATE POLICY frontdesk_photo_restriction ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING (bucket_id NOT IN ('guest-documents','payment-screenshots','cash-tx-attachments','staff-documents') OR public.can_access_frontdesk_data()) WITH CHECK (bucket_id NOT IN ('guest-documents','payment-screenshots','cash-tx-attachments','staff-documents') OR public.can_access_frontdesk_data());